#!/usr/bin/env python3
"""PTY minimal + Stage2 floor: CATCH handlers, uid/gid, TTOU."""
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]
SC = ROOT / "kernel" / "sysmain" / "syscall.c"
t = SC.read_text(encoding="utf-8")

def repl(old: str, new: str, label: str) -> None:
    global t
    if old not in t:
        if new in t:
            print(f"[skip] {label}")
            return
        raise SystemExit(f"missing: {label}")
    t = t.replace(old, new, 1)
    print(f"[ok] {label}")

# --- PTY defs after DEV_URANDOM ---
repl(
    """#define BFREE_GUEST_DEV_NULL_FD     0x3700
#define BFREE_GUEST_DEV_URANDOM_FD  0x3701
""",
    """#define BFREE_GUEST_DEV_NULL_FD     0x3700
#define BFREE_GUEST_DEV_URANDOM_FD  0x3701
#define BFREE_PTY_SLOTS             4
#define BFREE_PTY_BUF               512
#define BFREE_PTY_MASTER_BASE       0x3a00
#define BFREE_PTY_SLAVE_BASE        0x3a40
#define BFREE_GUEST_DEV_TTY_FD      0x3707
#define BFREE_GUEST_PTS_DIR_FD      0x3733
""",
    "pty defines",
)

# Signal CATCH + handler storage + uid
repl(
    """#define BFREE_SIG_DFL 0
#define BFREE_SIG_IGN 1
#define BFREE_NSIG    64
static uint8_t g_guest_sig_disp[BFREE_NSIG];
""",
    """#define BFREE_SIG_DFL   0
#define BFREE_SIG_IGN   1
#define BFREE_SIG_CATCH 2
#define BFREE_NSIG      64
static uint8_t g_guest_sig_disp[BFREE_NSIG];
static void *g_guest_sig_handler[BFREE_NSIG];
static uint32_t g_guest_uid;
static uint32_t g_guest_euid;
static uint32_t g_guest_gid;
static uint32_t g_guest_egid;
""",
    "catch+creds",
)

# PTY state after pipes or near eventfd
if "typedef struct {\n    int used;\n    int master_open;" not in t:
    insert_after = "static uint64_t g_guest_eventfd_val[BFREE_MAX_GUEST_EVENTFD];\n"
    pty_block = """
typedef struct {
    int used;
    int master_open;
    int slave_open;
    unsigned char m2s[BFREE_PTY_BUF];
    size_t m2s_len;
    unsigned char s2m[BFREE_PTY_BUF];
    size_t s2m_len;
} bfree_pty_t;
static bfree_pty_t g_guest_ptys[BFREE_PTY_SLOTS];

static int bfree_pty_master_fd(int slot)
{
    return (int)BFREE_PTY_MASTER_BASE + slot;
}
static int bfree_pty_slave_fd(int slot)
{
    return (int)BFREE_PTY_SLAVE_BASE + slot;
}
static int bfree_pty_slot_from_fd(int fd)
{
    if (fd >= (int)BFREE_PTY_MASTER_BASE && fd < (int)BFREE_PTY_MASTER_BASE + BFREE_PTY_SLOTS) {
        return fd - (int)BFREE_PTY_MASTER_BASE;
    }
    if (fd >= (int)BFREE_PTY_SLAVE_BASE && fd < (int)BFREE_PTY_SLAVE_BASE + BFREE_PTY_SLOTS) {
        return fd - (int)BFREE_PTY_SLAVE_BASE;
    }
    return -1;
}
static int bfree_pty_is_master(int fd)
{
    return fd >= (int)BFREE_PTY_MASTER_BASE && fd < (int)BFREE_PTY_MASTER_BASE + BFREE_PTY_SLOTS;
}
"""
    if insert_after not in t:
        raise SystemExit("no eventfd for pty insert")
    t = t.replace(insert_after, insert_after + pty_block, 1)
    print("[ok] pty structs")

# open /dev/ptmx, /dev/pts/N, /dev/tty, /dev/pts
repl(
    """    if (strcmp(path, "/dev/null") == 0) {
        /* Publish as small guest fd so close/dup2 behave normally. */
        return bfree_guest_fd_publish(BFREE_GUEST_DEV_NULL_FD);
    }
    if (strcmp(path, "/dev/urandom") == 0 || strcmp(path, "/dev/random") == 0) {
        return bfree_guest_fd_publish(BFREE_GUEST_DEV_URANDOM_FD);
    }
""",
    """    if (strcmp(path, "/dev/null") == 0) {
        /* Publish as small guest fd so close/dup2 behave normally. */
        return bfree_guest_fd_publish(BFREE_GUEST_DEV_NULL_FD);
    }
    if (strcmp(path, "/dev/urandom") == 0 || strcmp(path, "/dev/random") == 0) {
        return bfree_guest_fd_publish(BFREE_GUEST_DEV_URANDOM_FD);
    }
    if (strcmp(path, "/dev/tty") == 0) {
        return bfree_guest_fd_publish(BFREE_GUEST_DEV_TTY_FD);
    }
    if (strcmp(path, "/dev/pts") == 0 || (want_dir && strncmp(path, "/dev/pts/", 9) == 0 && path[9] == '\\0')) {
        return bfree_guest_vfile_publish_open(BFREE_GUEST_PTS_DIR_FD, (int)flags, 0);
    }
    if (strcmp(path, "/dev/ptmx") == 0) {
        int s;
        for (s = 0; s < BFREE_PTY_SLOTS; ++s) {
            if (!g_guest_ptys[s].used) {
                g_guest_ptys[s].used = 1;
                g_guest_ptys[s].master_open = 1;
                g_guest_ptys[s].slave_open = 0;
                g_guest_ptys[s].m2s_len = 0;
                g_guest_ptys[s].s2m_len = 0;
                return bfree_guest_fd_publish(bfree_pty_master_fd(s));
            }
        }
        return -24; /* EMFILE */
    }
    if (strncmp(path, "/dev/pts/", 9) == 0 && path[9] >= '0' && path[9] <= '9') {
        int s = path[9] - '0';
        if (s < 0 || s >= BFREE_PTY_SLOTS || !g_guest_ptys[s].used) {
            return -2;
        }
        g_guest_ptys[s].slave_open = 1;
        return bfree_guest_fd_publish(bfree_pty_slave_fd(s));
    }
""",
    "open pty paths",
)

# TIOCGPTN in ioctl — before ENOTTY return, after TIOCSPGRP block
repl(
    """        if (request == BFREE_LINUX_TIOCSPGRP) {
            if (arg == 0 || !bfree_user_ptr_mapped(arg)) {
                return -14;
            }
            {
                int pgrp = *(int *)(uintptr_t)arg;

                if (pgrp <= 0) {
                    return -22;
                }
                g_guest_tty_pgrp = pgrp;
            }
            return 0;
        }
    }
    (void)fd;
    (void)request;
    (void)arg;
    return -25; /* ENOTTY */
}
""",
    """        if (request == BFREE_LINUX_TIOCSPGRP) {
            if (arg == 0 || !bfree_user_ptr_mapped(arg)) {
                return -14;
            }
            {
                int pgrp = *(int *)(uintptr_t)arg;

                if (pgrp <= 0) {
                    return -22;
                }
                g_guest_tty_pgrp = pgrp;
            }
            return 0;
        }
    }
    /* PTY ioctls */
    {
        int resolved = bfree_guest_fd_resolve((int)fd);
        int slot = bfree_pty_slot_from_fd(resolved);
        if (slot >= 0) {
            if (request == 0x80045430U /* TIOCGPTN */) {
                if (arg == 0 || !bfree_user_ptr_mapped(arg)) {
                    return -14;
                }
                *(unsigned int *)(uintptr_t)arg = (unsigned int)slot;
                return 0;
            }
            if (request == 0x40045431U /* TIOCSPTLCK */ ||
                request == 0x5441 /* TIOCSCTTY rough */) {
                return 0;
            }
            if (request == BFREE_LINUX_TCGETS || request == BFREE_LINUX_TCSETS ||
                request == BFREE_LINUX_TIOCGWINSZ || request == BFREE_LINUX_TIOCGPGRP ||
                request == BFREE_LINUX_TIOCSPGRP) {
                /* fall through to termios below by treating as tty */
            } else {
                return 0; /* unlockpt/grantpt style success */
            }
        }
    }
    if (fd == (long)BFREE_GUEST_DEV_TTY_FD ||
        bfree_guest_fd_resolve((int)fd) == (int)BFREE_GUEST_DEV_TTY_FD) {
        if (request == BFREE_LINUX_TIOCGPGRP) {
            if (arg == 0 || !bfree_user_ptr_mapped(arg)) {
                return -14;
            }
            *(int *)(uintptr_t)arg = g_guest_tty_pgrp;
            return 0;
        }
        return 0;
    }
    (void)fd;
    (void)request;
    (void)arg;
    return -25; /* ENOTTY */
}
""",
    "pty ioctl",
)

# Need BFREE_LINUX_TCGETS etc - grep if defined
if "BFREE_LINUX_TCGETS" not in t:
    # find TIOCGPGRP define and add TCGETS nearby
    repl(
        "#define BFREE_LINUX_TIOCGPGRP  0x540F\n",
        "#define BFREE_LINUX_TCGETS    0x5401\n"
        "#define BFREE_LINUX_TCSETS    0x5402\n"
        "#define BFREE_LINUX_TIOCGWINSZ 0x5413\n"
        "#define BFREE_LINUX_TIOCGPGRP  0x540F\n"
        "#define BFREE_LINUX_TIOCSPGRP  0x5410\n",
        "termios defines",
    )

# Read/write PTY — insert early in sys_linux_read after resolve, before pipe
# Find: if (bfree_guest_is_pipe_rd(fd))
read_anchor = "    if (bfree_guest_is_pipe_rd(fd)) {"
pty_read = """    {
        int pslot = bfree_pty_slot_from_fd((int)fd);
        if (pslot >= 0 && g_guest_ptys[pslot].used) {
            bfree_pty_t *py = &g_guest_ptys[pslot];
            unsigned char *src;
            size_t *lenp;
            size_t n, i;
            if (buf == 0 || count <= 0 || !bfree_user_ptr_mapped(buf)) {
                return -14;
            }
            if (bfree_pty_is_master((int)fd)) {
                src = py->s2m;
                lenp = &py->s2m_len;
            } else {
                src = py->m2s;
                lenp = &py->m2s_len;
            }
            while (*lenp == 0) {
                int peer = bfree_pty_is_master((int)fd) ? py->slave_open : py->master_open;
                if (!peer) {
                    return 0; /* EOF */
                }
                {
                    int er = bfree_guest_sig_take_eintr();
                    if (er < 0) {
                        return er;
                    }
                }
                __asm__ volatile("sti; hlt" ::: "memory");
            }
            n = (size_t)count;
            if (n > *lenp) {
                n = *lenp;
            }
            for (i = 0; i < n; ++i) {
                ((uint8_t *)(uintptr_t)buf)[i] = src[i];
            }
            if (n < *lenp) {
                for (i = 0; i < *lenp - n; ++i) {
                    src[i] = src[i + n];
                }
            }
            *lenp -= n;
            return (long)n;
        }
    }
    if (fd == (long)BFREE_GUEST_DEV_TTY_FD) {
        return bfree_stdin_read_user(buf, count);
    }
"""
if "bfree_pty_slot_from_fd((int)fd)" not in t[t.find("sys_linux_read"):t.find("sys_linux_read")+2500]:
    if read_anchor not in t:
        raise SystemExit("no pipe_rd anchor")
    t = t.replace(read_anchor, pty_read + read_anchor, 1)
    print("[ok] pty read")

write_anchor = "    if (bfree_guest_is_pipe_wr(fd)) {"
pty_write = """    {
        int pslot = bfree_pty_slot_from_fd((int)fd);
        if (pslot >= 0 && g_guest_ptys[pslot].used) {
            bfree_pty_t *py = &g_guest_ptys[pslot];
            unsigned char *dst;
            size_t *lenp;
            size_t n, i, room;
            const uint8_t *src;
            if (buf == 0 || count <= 0 || !bfree_user_ptr_mapped(buf)) {
                return -14;
            }
            if (bfree_pty_is_master((int)fd)) {
                dst = py->m2s;
                lenp = &py->m2s_len;
            } else {
                dst = py->s2m;
                lenp = &py->s2m_len;
            }
            room = BFREE_PTY_BUF - *lenp;
            if (room == 0) {
                return -11; /* EAGAIN */
            }
            n = (size_t)count;
            if (n > room) {
                n = room;
            }
            src = (const uint8_t *)(uintptr_t)buf;
            for (i = 0; i < n; ++i) {
                dst[*lenp + i] = src[i];
            }
            *lenp += n;
            return (long)n;
        }
    }
    if (fd == (long)BFREE_GUEST_DEV_TTY_FD) {
        /* Stage2: SIGTTOU if background process group writes to tty */
        if (g_guest_fork_active) {
            int pg = bfree_process_getpgid(g_guest_fork_pid);
            if (pg > 0 && pg != g_guest_tty_pgrp &&
                g_guest_sig_disp[22] != BFREE_SIG_IGN &&
                !bfree_guest_sig_is_blocked(22)) {
                bfree_guest_sig_raise(22); /* SIGTTOU */
                return -4; /* EINTR */
            }
        }
        bfree_guest_console_write((const uint8_t *)(uintptr_t)buf, (size_t)count);
        return count;
    }
"""
# Also TTOU on console fd 1/2 write path - find console write in write()
if "bfree_pty_slot_from_fd((int)fd)" not in t[t.find("sys_linux_write"):t.find("sys_linux_write")+2000]:
    if write_anchor not in t:
        raise SystemExit("no pipe_wr")
    t = t.replace(write_anchor, pty_write + write_anchor, 1)
    print("[ok] pty write")

# close pty refs — find sys_linux_close beginning body
# After resolve in close, if pty slot, decrement opens

# sigaction CATCH
repl(
    """        if (handler == (void *)0) {
            g_guest_sig_disp[sig] = BFREE_SIG_DFL;
        } else if (handler == (void *)(uintptr_t)1) {
            g_guest_sig_disp[sig] = BFREE_SIG_IGN;
        } else {
            /* Custom handlers: record as IGN for delivery (no sigreturn yet). */
            g_guest_sig_disp[sig] = BFREE_SIG_IGN;
        }
""",
    """        if (handler == (void *)0) {
            g_guest_sig_disp[sig] = BFREE_SIG_DFL;
            g_guest_sig_handler[sig] = 0;
        } else if (handler == (void *)(uintptr_t)1) {
            g_guest_sig_disp[sig] = BFREE_SIG_IGN;
            g_guest_sig_handler[sig] = (void *)(uintptr_t)1;
        } else {
            /* Stage2: remember handler; deliver as pending→EINTR until frames exist. */
            g_guest_sig_disp[sig] = BFREE_SIG_CATCH;
            g_guest_sig_handler[sig] = handler;
        }
""",
    "sigaction catch",
)

# raise: CATCH should still set pending (not skip like IGN)
# Current raise skips IGN only - good for CATCH

# take_eintr: CATCH should return EINTR (not skip). Current only skips IGN - good

# getuid etc
repl(
    """static long sys_linux_getuid(void)
""",
    """static long sys_linux_setuid(long uid)
{
    g_guest_uid = (uint32_t)uid;
    g_guest_euid = (uint32_t)uid;
    return 0;
}
static long sys_linux_setgid(long gid)
{
    g_guest_gid = (uint32_t)gid;
    g_guest_egid = (uint32_t)gid;
    return 0;
}
static long sys_linux_getuid(void)
""",
    "setuid/setgid",
)

# Fix getuid body if it's just return 0
# Find and patch getuid/getgid/geteuid/getegid
import re
t2 = t
for name, var in [
    ("sys_linux_getuid", "g_guest_uid"),
    ("sys_linux_getgid", "g_guest_gid"),
    ("sys_linux_geteuid", "g_guest_euid"),
    ("sys_linux_getegid", "g_guest_egid"),
]:
    # pattern: static long name(void)\n{\n    return 0;\n}
    pat = rf"(static long {name}\(void\)\s*\{{\s*)return 0;"
    m = re.search(pat, t2)
    if m:
        t2 = t2[: m.start(1)] + m.group(1) + f"return (long){var};" + t2[m.end() :]
        print(f"[ok] {name} -> {var}")
    else:
        # maybe already different
        print(f"[warn] {name} body not stub")
t = t2

# Wire setuid/setgid in dispatch — near getuid cases
repl(
    """    case 102:
        return sys_linux_getuid();
""",
    """    case 105: /* setuid */
        return sys_linux_setuid(arg1);
    case 106: /* setgid */
        return sys_linux_setgid(arg1);
    case 102:
        return sys_linux_getuid();
""",
    "dispatch setuid",
)

# isatty for pty and /dev/tty
if "sys_linux_isatty" in t or "sys_isatty" in t:
    # find and extend
    pass

# stat for /dev/ptmx /dev/pts
repl(
    """    if (strcmp(path, "/dev/null") == 0) {
        return bfree_linux_stat_fill(statbuf, BFREE_LINUX_S_IFCHR | 0666U, 0);
    }
""",
    """    if (strcmp(path, "/dev/null") == 0) {
        return bfree_linux_stat_fill(statbuf, BFREE_LINUX_S_IFCHR | 0666U, 0);
    }
    if (strcmp(path, "/dev/ptmx") == 0 || strcmp(path, "/dev/tty") == 0 ||
        (strncmp(path, "/dev/pts/", 9) == 0 && path[9] != '\\0')) {
        return bfree_linux_stat_fill(statbuf, BFREE_LINUX_S_IFCHR | 0666U, 0);
    }
    if (strcmp(path, "/dev/pts") == 0) {
        return bfree_linux_stat_fill(statbuf, BFREE_LINUX_S_IFDIR | 0755U, 4096);
    }
""",
    "stat pty",
)

# access /dev/ptmx
# close: release pty
close_fn = t.find("static long sys_linux_close(long fd)")
if close_fn > 0 and "bfree_pty_slot_from_fd" not in t[close_fn:close_fn+800]:
    # insert after resolve
    marker = "static long sys_linux_close(long fd)\n{\n"
    # find first useful line after {
    idx = t.find("{", close_fn)
    # look for fd = bfree_guest_fd_resolve
    r = t.find("bfree_guest_fd_resolve", close_fn)
    if r > 0:
        # after that statement
        semi = t.find(";", r)
        insert = """
    {
        int pslot = bfree_pty_slot_from_fd((int)fd);
        if (pslot >= 0 && g_guest_ptys[pslot].used) {
            if (bfree_pty_is_master((int)fd)) {
                g_guest_ptys[pslot].master_open = 0;
            } else {
                g_guest_ptys[pslot].slave_open = 0;
            }
            if (!g_guest_ptys[pslot].master_open && !g_guest_ptys[pslot].slave_open) {
                g_guest_ptys[pslot].used = 0;
            }
        }
    }
"""
        # Actually resolve happens inside close - read the function
        print("[info] close at", close_fn, "resolve at", r)

SC.write_text(t, encoding="utf-8")
print("wrote", SC)
